from collections import Counter


def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    twos = [(r, c) for r in range(h) for c in range(w) if g[r][c] == 2]
    if not twos:
        return g
    rows = {r for r, _ in twos}
    cols = {c for _, c in twos}
    if len(rows) == 1:
        orient, axis = "h", next(iter(rows))
    elif len(cols) == 1:
        orient, axis = "v", next(iter(cols))
    else:
        return g

    counts = Counter(x for row in g for x in row if x != 2)
    background = counts.most_common(1)[0][0]
    objects = Counter(x for row in g for x in row if x not in (2, background))
    if not objects:
        return g
    color = objects.most_common(1)[0][0]
    pts = [(r, c) for r in range(h) for c in range(w) if g[r][c] == color]
    r0, r1 = min(r for r, _ in pts), max(r for r, _ in pts)
    c0, c1 = min(c for _, c in pts), max(c for _, c in pts)

    if orient == "v":
        if c0 > axis:
            delta = axis + 1 - c0
            marker = axis + 1 + (c1 - c0) + 1
        elif c1 < axis:
            delta = axis - 1 - c1
            marker = axis - 1 - (c1 - c0) - 1
        else:
            return g
        new_pts = [(r, c + delta) for r, c in pts]
        if not all(0 <= c < w for _, c in new_pts) or not 0 <= marker < w:
            return g
        for r, c in pts:
            g[r][c] = background
        for r, c in new_pts:
            g[r][c] = color
        for r in range(h):
            if g[r][marker] == background:
                g[r][marker] = 8
    else:
        if r0 > axis:
            delta = axis + 1 - r0
            marker = axis + 1 + (r1 - r0) + 1
        elif r1 < axis:
            delta = axis - 1 - r1
            marker = axis - 1 - (r1 - r0) - 1
        else:
            return g
        new_pts = [(r + delta, c) for r, c in pts]
        if not all(0 <= r < h for r, _ in new_pts) or not 0 <= marker < h:
            return g
        for r, c in pts:
            g[r][c] = background
        for r, c in new_pts:
            g[r][c] = color
        for c in range(w):
            if g[marker][c] == background:
                g[marker][c] = 8
    return g


